import React from 'react';
import ProductCard from './ProductCard';
import '../css/nouveautesection.css';

const Nouveautes = () => {
  const products = [
    {
      id: 1,
      image: '/path-to-abaya-image.jpg',
      title: 'Abaya Élégante Beige',
      category: 'Abaya',
      isNew: true,
      isFavorite: false
    },
    {
      id: 2,
      image: '/path-to-robe-image.jpg',
      title: 'Robe Longue Crème',
      category: 'Robes',
      isNew: true,
      isFavorite: false
    },
    {
      id: 3,
      image: '/path-to-tunique-image.jpg',
      title: 'Tunique Brodée Beige',
      category: 'Hauts',
      isNew: true,
      isFavorite: false
    }
  ];

  return (
    <section className="nouveautes-section">
      <div className="nouveautes-container">
        <div className="nouveautes-header">
          <h2 className="nouveautes-title">Nouveautés</h2>
          <p className="nouveautes-subtitle">
            Découvrez nos dernières créations, alliant tradition et modernité
          </p>
        </div>
        
        <div className="nouveautes-grid">
          {products.map(product => (
            <ProductCard 
              key={product.id}
              {...product}
            />
          ))}
        </div>
      </div>
    </section>
  );
};

export default Nouveautes;
